#!/bin/zsh
# 🪞️ T14 overlay hold 2 (one overlay-lane hold): sync the overlay to the live tree, apply F9 + the overlay-only id recorder
# + G12 (authoring seed) + P8 orphan + H9-L, run the F9 owners' lib tests recording the DefaultHasher→content_id map, rewrite every
# carrier from that map, re-run the same tests, then the F9 / H9-L laws (kernel content-id + addressing, host registry,
# hub linked-kind, wfc3d kind), the P8 orphan laws (verdict, reasoning + flow declared verbs; architect's runs with the
# owners), the TS content-id oracle, and ONE wasm32-wasip2 `--lib` check of every guest crate the four patches touch. Private build/target dirs inside the overlay.
O="/Users/ueli/Documents/semio/.🧬semio/🌐hub/s14-t14-overlay"
L="/Users/ueli/Documents/semio/.🧬semio/🌐hub/s14-t14-logs"
T=/Users/ueli/Documents/semio/.tmp-ticket/wp-t14
export CARGO_INCREMENTAL=0 RUST_MIN_STACK=33554432 CARGO_BUILD_BUILD_DIR="$O/.t14-build" CARGO_TARGET_DIR="$O/.t14-target"
OWNERS=(-p semio-s-artifact-architect-program -p semio-s-artifact-remodel-remodeling -p semio-s-artifact-note-note -p semio-s-artifact-block-3d -p semio-s-artifact-process-process3d -p semio-s-artifact-norm-din18599 -p semio-s-artifact-sequence-sequence -p semio-s-artifact-raster-raster -p semio-s-artifact-sourcing-curation -p semio-s-artifact-gis-gisterrain)
FEATURES=semio-s-artifact-block-3d/component-app-assembly,semio-s-artifact-gis-gisterrain/component-app-assembly
echo "HOLD $(date +%T)"
python3 $T/overlay.py sync "$O" > $L/hold2-sync.txt 2>&1 || { echo "SYNC-FAILED"; exit 2; }; tail -1 $L/hold2-sync.txt
python3 $T/f9/content-id.py --write --root "$O" > $L/hold2-f9-apply.txt 2>&1 || { echo "F9-APPLY-FAILED"; exit 3; }
python3 $T/f9/record-instrument.py --root "$O" > $L/hold2-record-apply.txt 2>&1 || { echo "RECORD-APPLY-FAILED"; exit 3; }
python3 /Users/ueli/Documents/semio/.tmp-ticket/wp-g12/g12-authoring-seed.py --write --root "$O" > $L/hold2-g12-apply.txt 2>&1 || { echo "G12-APPLY-FAILED"; exit 3; }
P8_ROOT="$O" python3 /Users/ueli/Documents/semio/.tmp-ticket/wp-p8/patches/p8-orphan.py --write > $L/hold2-orphan-apply.txt 2>&1 || { echo "ORPHAN-APPLY-FAILED"; exit 3; }
python3 $T/h9l/kind-label-patch.py --apply --root "$O" > $L/hold2-h9l-apply.txt 2>&1 || { echo "H9L-APPLY-FAILED"; exit 3; }
echo "APPLIED $(date +%T)"
cd "$O" || exit 2
rm -f $L/hold2-f9-map-1.tsv
T14_F9_RECORD=$L/hold2-f9-map-1.tsv nice -n 15 cargo test --no-fail-fast ${OWNERS[@]} --features $FEATURES --lib > $L/hold2-owners-1.txt 2>&1; echo "OWNERS-1 $? $(date +%T)"
python3 $T/f9/apply-map.py --map $L/hold2-f9-map-1.tsv --root "$O" --write > $L/hold2-map-apply.txt 2>&1; echo "MAP $? $(date +%T)"; head -3 $L/hold2-map-apply.txt
T14_F9_RECORD=$L/hold2-f9-map-2.tsv nice -n 15 cargo test --no-fail-fast ${OWNERS[@]} --features $FEATURES --lib > $L/hold2-owners-2.txt 2>&1; echo "OWNERS-2 $? $(date +%T)"
nice -n 15 cargo test --no-fail-fast -p semio-framework-os-kernel --lib -- content_id_is_the_specified_sha256_prefix shared_artifact_addressing > $L/hold2-kernel-laws.txt 2>&1; echo "KERNEL-LAWS $? $(date +%T)"
